package com.hbm.machine.silex;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.world.Containers;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;
public final class SilexBlock extends DummyableBlock {
 private static final MapCodec<SilexBlock> CODEC=simpleCodec(ignored->new SilexBlock());public SilexBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return CODEC;}@Override public int[] dimensions(){return new int[]{2,0,1,1,1,1};}@Override public int offset(){return 1;}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,pos,state,placer,stack);if(!level.isClientSide){var direction=placementFacing(state);var core=pos.relative(direction,-offset());for(var port:SilexBlockEntity.physicalPorts(core,direction))setPort(level,port,true);}}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new SilexBlockEntity(pos,state):isPort(state)?new SilexPort(pos,state):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,SilexContent.ENTITY.get(),SilexBlockEntity::tick):null;}
 /** Source FEL calls breakBlock(...,meta=0), not destroyBlock. The caller alone drops the machine. */
 public static void sourceBreakFromBeam(Level level,BlockPos core){var state=level.getBlockState(core);if(!(state.getBlock() instanceof SilexBlock block))return;if(level.getBlockState(core.above()).is(block))level.removeBlock(core.above(),false);if(level.getBlockEntity(core) instanceof SilexBlockEntity machine){Containers.dropContents(level,core,machine);level.updateNeighbourForOutputSignal(core,block);level.removeBlockEntity(core);level.invalidateCapabilities(core);}}
}
